import{_ as t,o as i,c as r,a5 as s}from"./chunks/framework.CsGesDJn.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/profile/3-3-4-update-client-profile/report3_spec.md","filePath":"feature/profile/3-3-4-update-client-profile/report3_spec.md"}'),l={name:"feature/profile/3-3-4-update-client-profile/report3_spec.md"};function o(n,e,a,d,p,c){return i(),r("div",null,[...e[0]||(e[0]=[s("<p><strong>3.3.4 Update Client Profile</strong></p><p>&gt; V2 (2026-10-02): ClientProfile reworked — owned by the User, independent of any Agency.</p><p><strong>Function Trigger</strong></p><p>Begins when a user creates a new Client Profile or saves edits to one of their existing Client Profiles, on the &quot;My Brand Profiles&quot; screen (/client-profiles).</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Any signed-in user, editing a Client Profile they own.</li><li><strong>Purpose</strong>: Let a user keep the brand information they represent up to date, or add a new brand profile. The email address cannot be set on a Client Profile — it is always the fixed identity of the owning user.</li><li><strong>Interface</strong>: The &quot;My Brand Profiles&quot; screen (3.3.3) in create/edit mode. Editable fields: display name (required), company, phone number, note, logo, website, industry, location, description, social links, plus brand fields. No email field for the owner&#39;s own identity, and no Agency selector anywhere in the form.</li><li><strong>Data Processing</strong>: The system resolves the caller&#39;s identity from the access token. For create, it inserts a new client_profiles row owned by the caller. For update, it looks up the profile by id, verifies userId matches the caller, writes the complete submitted field set over the record, stamps the update time, and persists. The record is never scoped to an Agency, so the update is visible wherever that profile is linked at once.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Brand Profile form (/client-profiles, create/edit):</p><ul><li>Center: display name input (required), company, phone number, note, logo, website, industry, location, description, social links, and brand-field inputs.</li><li>Buttons: Save (primary); Cancel; Delete (edit mode only, blocked while linked to an active workspace membership).</li><li>No email field is present in the form.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: displayName.</li><li><strong>Input optional</strong>: company, phone, note, logoUrl, website, industry, location, description, socialLinks, plus brand fields (contactName, contactEmail, companySize, instagramUrl, taxCode, address, tagline, foundedYear, budgetRange).</li><li><strong>System data</strong>: client_profiles — id, userId, displayName, company, phone, note, logoUrl, website, industry, location, description, socialLinks, plus the brand fields above, createdAt, updatedAt.</li><li><strong>Output</strong>: The complete Client Profile field set after the record is created or updated.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li>Create and update are separate requests (POST / PUT by id), not an upsert keyed by any (user, agency) pair.</li><li>The update is a full overwrite, not a partial patch — fields left out are written as empty.</li><li><strong>BR-38 (reworked)</strong>: A Client Profile is never scoped to a single Agency — editing it updates the one record everywhere it is linked.</li><li><strong>BR-19</strong>: Email and role are not mutable via this action; the request carries no email field for the owner&#39;s own account.</li><li>displayName is mandatory and must not be blank.</li><li>A Client Profile cannot be deleted while linked to an active workspace membership — CLIENT_PROFILE_IN_USE.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>displayName empty or blank → Display: <strong>MSG02</strong>.</li><li>Update/delete on a profile not owned by the caller → 403 CLIENT_PROFILE_NOT_OWNED.</li><li>Delete while linked to an active workspace membership → 409 CLIENT_PROFILE_IN_USE.</li><li>Missing, expired, or invalid access token → Display: <strong>MSG22</strong>.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>The user opens &quot;My Brand Profiles&quot;, fills the form, and clicks Save.</li><li>The application submits the complete set of Client Profile fields.</li><li>The system resolves the caller&#39;s identity from the access token.</li><li>For update, the system looks up the profile by id and verifies ownership.</li><li>The system writes the submitted fields over the record and stamps the update time.</li><li>The system persists the record and returns the complete Client Profile field set.</li><li>The application confirms success and refreshes the list; the new values appear everywhere the profile is linked at once.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>1.a1: displayName submitted empty or blank, the system displays <strong>MSG02</strong>. 1.a2: The user re-enters a display name and saves again.</li><li>4.a1: The profile id belongs to a different user → 403 CLIENT_PROFILE_NOT_OWNED. 4.a2: The application shows an access-denied error.</li><li>7.a1: An email address is submitted for the owner&#39;s own identity, it cannot be carried by the request. 7.a2: The field is silently ignored.</li><li>Delete.a1: The profile is linked to an active workspace membership → 409 CLIENT_PROFILE_IN_USE. Delete.a2: The user removes it from every workspace first.</li><li>N.a1: Missing, expired, or invalid access token at any step, the system displays <strong>MSG22</strong>. N.a2: The user signs in again at /login (3.2.2).</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>The Client Profile holds exactly the submitted field values; fields left out are empty (full overwrite, not a partial patch).</li><li>The updated values are visible wherever the profile is currently linked, across every Agency.</li><li>Other Client Profiles owned by the same or different users are unchanged.</li></ul>",15)])])}const h=t(l,[["render",o]]);export{f as __pageData,h as default};
